CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,email VARCHAR(150) NULL,pass_hash VARCHAR(255) NOT NULL,role ENUM('vendor','viewer','user','manager','admin') NOT NULL DEFAULT 'user',perms TEXT NULL,scope_all TINYINT(1) NOT NULL DEFAULT 1,notify_stock TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,last_login DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,notify_prefs VARCHAR(200) NULL,digest ENUM('off','daily','weekly') NOT NULL DEFAULT 'off',digest_last DATE NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description VARCHAR(255) NULL,parent_id INT NULL,INDEX(parent_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS custom_fields(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,label VARCHAR(100) NOT NULL,field_type ENUM('text','number','date','select') NOT NULL DEFAULT 'text',options TEXT NULL,sort INT NOT NULL DEFAULT 0,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS locations(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description VARCHAR(255) NULL,parent_id INT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS items(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,sku VARCHAR(80) NULL,barcode VARCHAR(100) NULL,type ENUM('consumable','returnable','asset') NOT NULL DEFAULT 'consumable',category_id INT NULL,location_id INT NULL,description TEXT NULL,qty DECIMAL(12,2) NOT NULL DEFAULT 0,unit VARCHAR(20) NULL,min_qty DECIMAL(12,2) NOT NULL DEFAULT 0,par_qty DECIMAL(12,2) NULL,reorder_qty DECIMAL(12,2) NULL,unit_cost DECIMAL(12,2) NULL,serial VARCHAR(100) NULL,status ENUM('available','checked_out','maintenance','retired') NOT NULL DEFAULT 'available',custom_data TEXT NULL,archived_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,import_batch INT NULL,deleted_at DATETIME NULL,deleted_by INT NULL,INDEX(sku),INDEX(barcode),INDEX(archived_at),INDEX(type),INDEX(category_id),INDEX(location_id),INDEX(import_batch),INDEX(deleted_at),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transactions(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,user_id INT NULL,type VARCHAR(20) NOT NULL,qty DECIMAL(12,2) NOT NULL DEFAULT 0,balance DECIMAL(12,2) NULL,note VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,incident_id INT NULL,undone_at DATETIME NULL,undo_of INT NULL,INDEX(item_id),INDEX(created_at),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checkouts(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,borrower VARCHAR(100) NOT NULL,person_id INT NULL,user_id INT NULL,out_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,due_at DATE NULL,in_at DATETIME NULL,note VARCHAR(255) NULL,incident_id INT NULL,overdue_notified_on DATE NULL,INDEX(item_id),INDEX(in_at),INDEX(person_id),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checklists(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description VARCHAR(255) NULL,active TINYINT(1) NOT NULL DEFAULT 1,notify_complete TEXT NULL,notify_fail TEXT NULL,vehicle_id INT NULL,frequency_days INT NULL,overdue_notified_on DATE NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,require_photo TINYINT(1) NOT NULL DEFAULT 0,INDEX(vehicle_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checklist_items(id INT AUTO_INCREMENT PRIMARY KEY,checklist_id INT NOT NULL,label VARCHAR(255) NOT NULL,sort INT NOT NULL DEFAULT 0,section_id INT NULL,kind ENUM('ok','count','level','value') NOT NULL DEFAULT 'ok',expect_qty DECIMAL(12,2) NULL,min_level TINYINT NULL,item_id INT NULL,ref_photo VARCHAR(80) NULL,FOREIGN KEY(checklist_id) REFERENCES checklists(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checklist_runs(id INT AUTO_INCREMENT PRIMARY KEY,checklist_id INT NOT NULL,user_id INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,notes VARCHAR(255) NULL,issues INT NOT NULL DEFAULT 0,INDEX(created_at),FOREIGN KEY(checklist_id) REFERENCES checklists(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checklist_run_items(id INT AUTO_INCREMENT PRIMARY KEY,run_id INT NOT NULL,label VARCHAR(255) NOT NULL,status ENUM('ok','missing','issue') NOT NULL DEFAULT 'ok',note VARCHAR(255) NULL,kind VARCHAR(10) NOT NULL DEFAULT 'ok',section VARCHAR(100) NULL,item_id INT NULL,expected DECIMAL(12,2) NULL,actual VARCHAR(60) NULL,photo VARCHAR(80) NULL,FOREIGN KEY(run_id) REFERENCES checklist_runs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(60) NOT NULL,details VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),INDEX(user_id),INDEX(action)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS item_photos(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,filename VARCHAR(80) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(item_id),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(60) NOT NULL PRIMARY KEY,v TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NULL,ip VARCHAR(45) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(username),INDEX(ip),INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS item_history(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,user_id INT NULL,action VARCHAR(20) NOT NULL,field VARCHAR(40) NULL,old_value TEXT NULL,new_value TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(item_id),INDEX(created_at),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS people(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,badge_code VARCHAR(100) NULL,department VARCHAR(100) NULL,user_id INT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,phone VARCHAR(40) NULL,is_agency TINYINT(1) NOT NULL DEFAULT 0,INDEX(badge_code),INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_access(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NULL,location_id INT NULL,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS item_codes(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,code VARCHAR(100) NOT NULL,code_type VARCHAR(12) NOT NULL DEFAULT 'other',is_primary TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(item_id),INDEX(code),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vendors(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,contact_name VARCHAR(100) NULL,phone VARCHAR(40) NULL,email VARCHAR(150) NULL,website VARCHAR(200) NULL,account_no VARCHAR(60) NULL,address VARCHAR(255) NULL,notes TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS item_vendors(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,vendor_id INT NOT NULL,rank_no INT NOT NULL DEFAULT 1,part_no VARCHAR(80) NULL,unit_cost DECIMAL(12,2) NULL,unavailable TINYINT(1) NOT NULL DEFAULT 0,unavail_note VARCHAR(255) NULL,INDEX(item_id),INDEX(vendor_id),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE,FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS item_lots(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,lot_no VARCHAR(60) NULL,qty DECIMAL(12,2) NULL,expires_on DATE NULL,note VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reminded_stage TINYINT NOT NULL DEFAULT 0,INDEX(item_id),INDEX(expires_on),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS alert_notes(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,user_id INT NULL,kind VARCHAR(10) NOT NULL DEFAULT 'note',note VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,cleared_at DATETIME NULL,INDEX(item_id),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS passkeys(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,credential_id VARCHAR(400) NOT NULL,public_key TEXT NOT NULL,alg INT NOT NULL,sign_count BIGINT UNSIGNED NOT NULL DEFAULT 0,name VARCHAR(80) NOT NULL,transports VARCHAR(100) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_used DATETIME NULL,UNIQUE KEY(credential_id(190)),INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS email_queue(id INT AUTO_INCREMENT PRIMARY KEY,to_email VARCHAR(190) NOT NULL,subject VARCHAR(200) NOT NULL,body_html MEDIUMTEXT NOT NULL,body_text MEDIUMTEXT NOT NULL,event VARCHAR(40) NULL,status ENUM('pending','sent','failed') NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(250) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,INDEX(status),INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(token_hash),INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS incidents(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,kind VARCHAR(40) NULL,starts_on DATE NULL,notes VARCHAR(500) NULL,status ENUM('open','closed') NOT NULL DEFAULT 'open',created_by INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,closed_by INT NULL,INDEX(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS issues(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,holder_name VARCHAR(100) NOT NULL,person_id INT NULL,incident_id INT NULL,qty_out DECIMAL(12,2) NOT NULL,qty_back DECIMAL(12,2) NOT NULL DEFAULT 0,qty_gone DECIMAL(12,2) NOT NULL DEFAULT 0,qty_moved DECIMAL(12,2) NOT NULL DEFAULT 0,note VARCHAR(255) NULL,issued_by INT NULL,issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,INDEX(item_id),INDEX(person_id),INDEX(incident_id),INDEX(closed_at),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS issue_events(id INT AUTO_INCREMENT PRIMARY KEY,issue_id INT NOT NULL,event VARCHAR(20) NOT NULL,qty DECIMAL(12,2) NOT NULL DEFAULT 0,outcome VARCHAR(20) NULL,by_user INT NULL,by_name VARCHAR(100) NULL,from_name VARCHAR(100) NULL,to_name VARCHAR(100) NULL,note VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(issue_id),FOREIGN KEY(issue_id) REFERENCES issues(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,kind ENUM('agency','personal') NOT NULL DEFAULT 'agency',owner_person_id INT NULL,item_id INT NULL,plate VARCHAR(30) NULL,notes VARCHAR(500) NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(owner_person_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicle_users(vehicle_id INT NOT NULL,user_id INT NOT NULL,PRIMARY KEY(vehicle_id,user_id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checklist_sections(id INT AUTO_INCREMENT PRIMARY KEY,checklist_id INT NOT NULL,name VARCHAR(100) NOT NULL,sort INT NOT NULL DEFAULT 0,ref_photo VARCHAR(80) NULL,FOREIGN KEY(checklist_id) REFERENCES checklists(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kits(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description VARCHAR(255) NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kit_items(id INT AUTO_INCREMENT PRIMARY KEY,kit_id INT NOT NULL,item_id INT NOT NULL,qty DECIMAL(12,2) NOT NULL DEFAULT 1,FOREIGN KEY(kit_id) REFERENCES kits(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documents(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NULL,vehicle_id INT NULL,title VARCHAR(150) NOT NULL,filename VARCHAR(80) NOT NULL,orig_name VARCHAR(190) NOT NULL,size INT NOT NULL DEFAULT 0,uploaded_by INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(item_id),INDEX(vehicle_id),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recounts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,scope VARCHAR(150) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recount_lines(id INT AUTO_INCREMENT PRIMARY KEY,recount_id INT NOT NULL,item_id INT NULL,item_name VARCHAR(150) NOT NULL,expected DECIMAL(12,2) NOT NULL,counted DECIMAL(12,2) NOT NULL,FOREIGN KEY(recount_id) REFERENCES recounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservations(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,incident_id INT NULL,borrower VARCHAR(100) NOT NULL,person_id INT NULL,qty DECIMAL(12,2) NOT NULL DEFAULT 1,starts_on DATE NOT NULL,ends_on DATE NOT NULL,status ENUM('reserved','fulfilled','cancelled') NOT NULL DEFAULT 'reserved',note VARCHAR(255) NULL,created_by INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reminded_on DATE NULL,INDEX(item_id),INDEX(incident_id),INDEX(starts_on),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS maintenance_tasks(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,title VARCHAR(150) NOT NULL,every_days INT NOT NULL,last_done DATE NULL,next_due DATE NOT NULL,notes VARCHAR(255) NULL,active TINYINT(1) NOT NULL DEFAULT 1,notified_on DATE NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(item_id),INDEX(next_due),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS maintenance_log(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,title VARCHAR(150) NOT NULL,done_on DATE NOT NULL,user_id INT NULL,note VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(item_id),FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS check_photos(id INT AUTO_INCREMENT PRIMARY KEY,run_item_id INT NOT NULL,filename VARCHAR(80) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(run_item_id),FOREIGN KEY(run_item_id) REFERENCES checklist_run_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS report_schedules(id INT AUTO_INCREMENT PRIMARY KEY,report VARCHAR(20) NOT NULL,params VARCHAR(200) NULL,frequency ENUM('daily','weekly','monthly') NOT NULL DEFAULT 'weekly',recipients TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,last_sent DATE NULL,created_by INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS import_batches(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,summary VARCHAR(300) NULL,made TEXT NULL,undone_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS barcode_cache(code VARCHAR(40) NOT NULL PRIMARY KEY,found TINYINT(1) NOT NULL DEFAULT 0,name VARCHAR(200) NULL,brand VARCHAR(120) NULL,size VARCHAR(80) NULL,category VARCHAR(160) NULL,image VARCHAR(80) NULL,source VARCHAR(30) NULL,looked_up_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
